package mz.bam.seeky.android;

import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;

/** Private conversation snapshots. Source context is fixed per conversation, never the whole library. */
final class SeekyAiStore {
 final File root;final Context app;SeekyAiStore(Context c){app=c.getApplicationContext();root=new File(c.getFilesDir(),"seeky-ai-conversations");root.mkdirs();}SeekyAiStore(File root){this.root=root;app=null;root.mkdirs();}
 static final class Session {
  final JSONObject data;final List<SeekyAiCore.Message> messages=new ArrayList<>();
  Session(JSONObject data)throws JSONException{this.data=data;JSONArray turns=data.optJSONArray("messages");if(turns!=null)for(int n=0;n<turns.length();n++){JSONObject item=turns.getJSONObject(n);String role=item.getString("role"),text=SeekyAiCore.valid(item.getString("text"),SeekyAiCore.ANSWER,"Mensagem");if(!role.equals(n%2==0?"user":"assistant"))throw new JSONException("Conversa inválida.");messages.add(new SeekyAiCore.Message(role,text));}if(messages.size()>40||messages.size()%2!=0||context().length()>SeekyAiCore.CONTEXT)throw new JSONException("Conversa inválida.");}
  String s(String key){return data.optString(key,"");}long n(String key){return data.optLong(key,0);}String id(){return s("id");}String context(){return s("context");}
  void put(String key,Object value){try{data.put(key,value);}catch(JSONException e){throw new IllegalStateException(e);}}
  void append(String question,SeekyAiCore.Result answer){messages.add(new SeekyAiCore.Message("user",question));messages.add(new SeekyAiCore.Message("assistant",answer.text));put("pending","");put("partial",answer.partial);}
  boolean full(){int size=context().length();for(SeekyAiCore.Message m:messages)size+=m.text.length();return messages.size()>=40||size>180000;}
 }
 Session create(String title,String context,String label,String uri,String mime,String name,int part,long material,long subject)throws Exception{JSONObject value=new JSONObject().put("id",UUID.randomUUID().toString()).put("title",AudioTitles.limit(title,200,600)).put("context",context).put("label",AudioTitles.limit(label,240,720)).put("uri",uri).put("mime",mime).put("name",name).put("part",part).put("material",material).put("subject",subject).put("created",System.currentTimeMillis());Session s=new Session(value);save(s);return s;}
 File file(String id)throws IOException{if(id==null||!id.matches("[a-f0-9-]{36}"))throw new IOException("Conversa indisponível.");File f=app==null?new File(root,id+".json"):new File(app.getSharedPreferences("reading_tools",0).getString("conversation_file_"+id,new File(root,id+".json").getPath()));if(!f.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator))throw new IOException("Conversa indisponível.");return f;}
 Session load(String id)throws Exception{File f=file(id);if(!f.isFile()||f.length()>2097152)throw new IOException("Conversa indisponível.");String raw=new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);JsonBudget.check(raw,16,256);Session s=new Session(new JSONObject(raw));if(!id.equals(s.id()))throw new IOException("Conversa inválida.");return s;}
 synchronized void save(Session s)throws Exception{JSONArray turns=new JSONArray();for(SeekyAiCore.Message m:s.messages)turns.put(new JSONObject().put("role",m.role).put("text",m.text));s.data.put("messages",turns).put("updated",System.currentTimeMillis());byte[] bytes=s.data.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>2097152)throw new IOException("Conversa demasiado longa. Comece uma nova conversa.");File target=file(s.id()),tmp=new File(root,s.id()+".new");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(bytes);out.getFD().sync();}try{Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);}}
 Set<String> identities(){Set<String> ids=new HashSet<>();File[] files=root.listFiles((d,n)->n.matches("[a-f0-9-]{36}\\.json"));if(files!=null)for(File f:files)ids.add(f.getName().substring(0,36));if(app!=null)for(String key:app.getSharedPreferences("reading_tools",0).getAll().keySet())if(key.startsWith("conversation_file_")){String id=key.substring("conversation_file_".length());if(id.matches("[a-f0-9-]{36}"))ids.add(id);}return ids;}
 List<File> activeFiles(){List<File> out=new ArrayList<>();for(String id:identities())try{Session s=load(id);out.add(file(s.id()));}catch(Exception ignored){}return out;}
 List<Session> list(){List<File> files=activeFiles();files.sort((a,b)->Long.compare(b.lastModified(),a.lastModified()));List<Session> result=new ArrayList<>();for(File f:files)try{String raw=new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);Session session=new Session(new JSONObject(raw));if(!session.messages.isEmpty()||!session.s("pending").isEmpty())result.add(session);if(result.size()>=50)break;}catch(Exception ignored){}return result;}
 void delete(String id)throws IOException{file(id).delete();new File(root,id+".new").delete();}
}
